WI = "docs/autoscaling/application/userguide/what-is-application-auto-scaling"
GS = "docs/autoscaling/application/userguide/getting-started"
IS = "docs/autoscaling/application/userguide/integrated-services-list"
RZ = "docs/AWSEC2/latest/UserGuide/ec2-instance-resize"
CT = "docs/AWSEC2/latest/UserGuide/change-instance-type-of-ebs-backed-instance"
RO = "docs/autoscaling/ec2/userguide/instance-refresh-overview"
FACTS = [
F("aws-auto-scaling-aas-policy-types", "capability",
  "Application Auto Scaling offers target tracking, step, scheduled and predictive scaling for the resources it supports.",
  "Which scaling policy types does Application Auto Scaling offer?",
  ["Target tracking scaling", "Step scaling", "Scheduled scaling", "Predictive scaling"],
  [(WI, "**Target tracking scaling** – Scale a resource based on a target value for a specific CloudWatch metric."),
   (WI, "**Step scaling** – Scale a resource based on a set of scaling adjustments that vary based on the size of the alarm breach."),
   (WI, "**Scheduled scaling** – Scale a resource one time only or on a recurring schedule."),
   (WI, "**Predictive scaling** – Scale a resource proactively to match anticipated load based on historical data.")],
  ["3.2.K4"]),
F("aws-auto-scaling-aas-scalable-target-identity", "behavior",
  "In Application Auto Scaling, a scalable target is the resource you want to scale, identified by a service namespace, a resource ID and a scalable dimension.",
  "What is a scalable target in Application Auto Scaling?",
  ["service namespace, resource ID, and scalable dimension", "specify the resource that you want to scale"],
  (GS, "An entity that you create to specify the resource that you want to scale. Each scalable target is uniquely identified by a service namespace, resource ID, and scalable dimension, which represents some capacity dimension of the underlying service."),
  ["3.2.K4"]),
F("aws-auto-scaling-aas-scalable-dimension-examples", "capability",
  "Examples of scalable dimensions: an ECS service scales its task count, a DynamoDB table scales its read and write capacity (and that of its global secondary indexes), and an Aurora cluster scales its replica count.",
  "What does Application Auto Scaling change for ECS, DynamoDB and Aurora?",
  ["auto scaling of its task count", "the read and write capacity of the table", "scaling of its replica count"],
  (GS, "For example, an Amazon ECS service supports auto scaling of its task count, a DynamoDB table supports auto scaling of the read and write capacity of the table and its global secondary indexes, and an Aurora cluster supports scaling of its replica count."),
  ["3.2.K4", "3.2.S1"]),
F("aws-auto-scaling-aas-min-max-enforced", "behavior",
  "Each scalable target has a minimum and maximum capacity that scaling policies never go beyond; capacity changed out of band outside that range is brought back into it the next time a policy runs or RegisterScalableTarget is called.",
  "What happens if someone changes a resource's capacity outside the scalable target's range?",
  ["Scaling policies will never go higher or lower", "updated to comply with the set minimum"],
  (GS, "Each scalable target also has a minimum and maximum capacity. Scaling policies will never go higher or lower than the minimum-maximum range. You can make out-of-band changes directly to the underlying resource that are outside of this range, which Application Auto Scaling doesn't know about. However, anytime a scaling policy is invoked or the `RegisterScalableTarget` API is called, Application Auto Scaling retrieves the current capacity and compares it to the minimum and maximum capacity. If it falls outside of the minimum-maximum range, then the capacity is updated to comply with the set minimum and maximum."),
  ["3.2.K4"], rel="extended"),
F("aws-auto-scaling-aas-cooldown-larger-scale-out", "behavior",
  "Application Auto Scaling keeps evaluating metrics during a cooldown period, and if a larger scale-out is needed during the cooldown the policy scales out immediately.",
  "Does an Application Auto Scaling cooldown block a bigger scale-out?",
  ["continues to evaluate metrics during the cooldown", "the scaling policy scales out immediately"],
  (GS, "A cooldown period between scaling activities lets the resource stabilize before another scaling activity starts. Application Auto Scaling continues to evaluate metrics during the cooldown period. When the cooldown period ends, the scaling policy initiates another scaling activity if needed. While a cooldown period is in effect, if a larger scale out is necessary based on the current metric value, the scaling policy scales out immediately."),
  ["3.2.S2"], rel="extended"),
F("aws-auto-scaling-aas-scheduled-modifies-min-max", "behavior",
  "Application Auto Scaling scheduled actions work by changing the scalable target's minimum and maximum capacity at a specific date and time.",
  "How does a scheduled action in Application Auto Scaling change capacity?",
  ["modifying the minimum and maximum capacity"],
  (GS, "Scheduled actions automatically scale resources at a specific date and time. They work by modifying the minimum and maximum capacity for a scalable target, and therefore can be used to scale in and out on a schedule by setting the minimum capacity high or the maximum capacity low."),
  ["3.2.K4"], rel="extended"),
F("aws-auto-scaling-aas-off-by-default", "default",
  "For the services that integrate with Application Auto Scaling, auto scaling is an optional feature that is disabled by default in almost all cases.",
  "Is auto scaling turned on by default for services such as ECS or DynamoDB through Application Auto Scaling?",
  ["disabled by default in almost all cases", "an optional feature of the service"],
  (IS, "Application Auto Scaling integrates with other AWS services so that you can add scaling capabilities to meet your application's demand. Auto scaling is an optional feature of the service that is disabled by default in almost all cases."),
  ["3.2.K4"], rel="extended", scope="per integrated AWS service", dom="default", adjustable=True),
F("aws-auto-scaling-aas-scaling-out-in-limits", "behavior",
  "With scaling policies set, Application Auto Scaling cannot scale a scalable target in below its minimum capacity or out above its maximum capacity.",
  "Can an Application Auto Scaling policy go below the minimum capacity?",
  ["lower than its minimum capacity", "higher than its maximum capacity"],
  [(GS, "When Application Auto Scaling automatically decreases capacity for a scalable target, the scalable target *scales in*. When scaling policies are set, they cannot scale in the scalable target lower than its minimum capacity."),
   (GS, "When Application Auto Scaling automatically increases capacity for a scalable target, the scalable target *scales out*. When scaling policies are set, they cannot scale out the scalable target higher than its maximum capacity.")],
  ["3.2.K4"], rel="reference"),
F("ec2-auto-scaling-vertical-resize-instance-type", "capability",
  "Vertical scaling of a single instance means resizing it by changing its instance type, and you then pay the rate of the new instance type.",
  "How do you scale a single EC2 instance up, and what changes in the bill?",
  ["resize your instance by changing its instance type", "paying the rate of the new instance type"],
  [(RZ, "As your needs change, you might find that your Amazon EC2 instance is too big or too small for its workload. If this is the case, you can resize your instance by changing its instance type."),
   (RZ, "When you change the instance type, you'll start paying the rate of the new instance type.")],
  ["2.1.K6", "4.2.S2"]),
F("ec2-auto-scaling-vertical-stop-required", "restriction",
  "You must stop an EBS-backed instance before you can change its instance type, so vertical scaling needs planned downtime.",
  "Can you change an instance's type while it is running?",
  ["You must stop your instance", "plan for downtime"],
  (CT, "You must stop your instance before you can change its instance type. Ensure that you plan for downtime while your instance is stopped."),
  ["2.1.K6", "4.2.S2"]),
F("ec2-auto-scaling-vertical-stopped-group-instance-unhealthy", "behavior",
  "If you stop an instance in an Auto Scaling group to change its type, EC2 Auto Scaling marks it unhealthy and might replace it; suspend the scaling processes to prevent this.",
  "What happens if you stop an Auto Scaling instance to resize it?",
  ["marks the stopped instance as unhealthy", "suspend the scaling processes for the group"],
  (CT, "If your instance is in an Auto Scaling group, the Amazon EC2 Auto Scaling service marks the stopped instance as unhealthy, and might terminate it and launch a replacement instance. To prevent this, you can suspend the scaling processes for the group while you're changing the instance type."),
  ["2.1.K6", "2.2.S4"]),
F("ec2-auto-scaling-instance-refresh-skip-matching-user-data-gap", "restriction",
  "Skip matching does not check for code changes deployed from a user data script, so turn it off when user data pulls new code.",
  "Does skip matching notice new code that a user data script installs?",
  ["doesn't check for code changes", "turn off skip matching"],
  (RO, "**Deploying code via user data** — Skip matching doesn't check for code changes that are deployed from a user data script. If you use user data to pull new code and install these updates on new instances, we recommend that you turn off skip matching to make sure that all instances receive your latest code, even without a launch template version update."),
  ["2.2.K7"], rel="extended"),
]
